def add_triage_tags(subject: str, existing_tags: list[str] | None = None) -> list[str]:
    # Safe: allocate a fresh list on each call instead of `existing_tags=[]`
    tags = list(existing_tags) if existing_tags is not None else []
    lowered = subject.lower()
    if "refund" in lowered or "charged twice" in lowered:
        tags.append("billing_urgent")
    if "security" in lowered:
        tags.append("security_escalation")
    return tags

import json
from pathlib import Path

def load_ticket_dataset(path: Path) -> list[dict]:
    try:
        raw = path.read_text(encoding="utf-8")
        data = json.loads(raw)
    except FileNotFoundError as exc:
        raise RuntimeError(f"Dataset missing at {path}") from exc
    except json.JSONDecodeError as exc:
        raise ValueError(f"Malformed JSON at line {exc.lineno}: {exc.msg}") from exc
    if not isinstance(data, list):
        raise ValueError("Expected top-level JSON array of tickets")
    return data

def extract_domain(email: str) -> str | None:
    if "@" not in email:
        return None
    return email.rsplit("@", maxsplit=1)[-1].lower()

def prioritize(domains: list[str], vip_map: dict[str, int]) -> int:
    return max((vip_map.get(d, 0) for d in domains), default=0)

