import random
import time
import httpx

RETRYABLE_STATUSES = {429, 500, 502, 503, 504}

def post_with_backoff(client: httpx.Client, path: str, payload: dict, headers: dict, max_attempts: int = 3) -> dict:
    for attempt in range(max_attempts):
        try:
            resp = client.post(path, json=payload, headers=headers, timeout=10.0)
            if resp.status_code in RETRYABLE_STATUSES and attempt < max_attempts - 1:
                delay = min(1.0 * (2 ** attempt) + random.uniform(0.0, 0.5), 10.0)
                time.sleep(delay)
                continue
            resp.raise_for_status()
            return resp.json()
        except (httpx.TimeoutException, httpx.ConnectError):
            if attempt == max_attempts - 1:
                raise
            time.sleep(1.0 * (2 ** attempt) + random.uniform(0.0, 0.5))
    raise RuntimeError("Unreachable")

