PROCESSED_RESULTS: dict[str, dict] = {}

def handle_triage_idempotent(idempotency_key: str, ticket: dict, run_fn) -> dict:
    if idempotency_key in PROCESSED_RESULTS:
        return {**PROCESSED_RESULTS[idempotency_key], "deduplicated": True}
    result = run_fn(ticket)
    PROCESSED_RESULTS[idempotency_key] = result
    return {**result, "deduplicated": False}

