def extract_completion_text(api_response: dict) -> str:
    choice = api_response["choices"][0]
    finish = choice.get("finish_reason")
    if finish == "length":
        raise ValueError("LLM output truncated at max_tokens before finishing JSON")
    if finish == "content_filter":
        raise ValueError("LLM output blocked by provider safety filter")
    return choice["message"]["content"] or ""

