def estimate_call_cost_usd(
    input_tokens: int,
    output_tokens: int,
    input_per_million_usd: float,
    output_per_million_usd: float,
) -> float:
    in_cost = (input_tokens / 1_000_000) * input_per_million_usd
    out_cost = (output_tokens / 1_000_000) * output_per_million_usd
    return round(in_cost + out_cost, 6)

def score_candidate(predictions: list[dict], labels: list[dict]) -> dict:
    total = len(labels)
    exact_category = sum(p["category"] == y["category"] for p, y in zip(predictions, labels))
    missed_escalations = sum(
        (not p["needs_human_approval"]) and y["needs_human_approval"]
        for p, y in zip(predictions, labels)
    )
    return {
        "total": total,
        "accuracy": round(exact_category / total, 3),
        "missed_escalations": missed_escalations,  # Critical business safety metric!
    }

