def call_llm_direct(api_key: str, messages: list[dict], endpoint: str) -> dict:
    with httpx.Client(timeout=25.0) as client:
        resp = client.post(
            endpoint,
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            json={
                "model": "gpt-4.1-mini",
                "temperature": 0.0,
                "messages": messages,
                "max_tokens": 300,
            },
        )
        resp.raise_for_status()
        return resp.json()

