        return {"route": "drop_spam"}

    # 2. Deterministic DB lookup (never let LLM guess customer tier!)
    account = lookup_account_in_db(ticket["sender"])

    # 3. Bounded LLM step: classify unstructured body only
    decision = llm_classify_and_draft(ticket["subject"], ticket["body"])

    # 4. Deterministic routing & safety rules (never delegate approval policy to LLM!)
